+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridTester;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.stream.IntStream;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    private static final int FIRST_NAME = 0;
+    private static final int LAST_NAME = 1;
+    private static final int SPECIALTIES = 2;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002")
+    void navigationMenuLeadsToVeterinarians() {
+        navigate(VetsView.class);
+
+        SideNavItem vetsLink = assertDoesNotThrow(() -> find(SideNavItem.class)
+                        .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected a Veterinarians item in the navigation menu");
+        assertEquals("vets", vetsLink.getPath());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void veterinariansAreShownWithoutAuthentication() {
+        // No login is performed before navigating, covering BR-003 (Anonymous Access).
+        assertDoesNotThrow(() -> navigate(VetsView.class),
+                "Expected /vets to resolve to VetsView without authentication");
+        assertEquals("vets", UI.getCurrent()
+                .getInternals().getActiveViewLocation().getPath());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsFirstNameLastNameAndSpecialties() {
+        navigate(VetsView.class);
+        GridTester<Grid<Object>, Object> grid = vetsGrid();
+
+        assertEquals("First Name", grid.getHeaderCell(FIRST_NAME));
+        assertEquals("Last Name", grid.getHeaderCell(LAST_NAME));
+        assertEquals("Specialties", grid.getHeaderCell(SPECIALTIES));
+        assertEquals(6, grid.size(), "Expected all six seeded veterinarians");
+
+        // Ordered by last name: Carter, Douglas, Jenkins, Leary, Ortega, Stevens.
+        assertEquals("Helen", grid.getCellText(3, FIRST_NAME));
+        assertEquals("Leary", grid.getCellText(3, LAST_NAME));
+        assertEquals("radiology", grid.getCellText(3, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void vetWithoutSpecialtiesShowsNone() {
+        navigate(VetsView.class);
+        GridTester<Grid<Object>, Object> grid = vetsGrid();
+
+        assertEquals("James", grid.getCellText(0, FIRST_NAME));
+        assertEquals("Carter", grid.getCellText(0, LAST_NAME));
+        assertEquals("none", grid.getCellText(0, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreListedAlphabetically() {
+        navigate(VetsView.class);
+        GridTester<Grid<Object>, Object> grid = vetsGrid();
+
+        // Seeded as surgery (2) then dentistry (3); shown alphabetically.
+        assertEquals("Linda", grid.getCellText(1, FIRST_NAME));
+        assertEquals("Douglas", grid.getCellText(1, LAST_NAME));
+        assertEquals("dentistry, surgery", grid.getCellText(1, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridLoadsVeterinariansLazilyFromTheBackend() {
+        IntStream.rangeClosed(1, 120).forEach(i -> dsl.insertInto(VETS)
+                .set(VETS.FIRST_NAME, "Vet")
+                .set(VETS.LAST_NAME, "Zz%03d".formatted(i))
+                .execute());
+
+        navigate(VetsView.class);
+        Grid<?> grid = find(Grid.class).single();
+
+        assertFalse(grid.getDataProvider().isInMemory(),
+                "Expected a callback data provider that fetches rows as the visitor scrolls");
+        GridTester<Grid<Object>, Object> tester = vetsGrid();
+        assertEquals(126, tester.size(), "Expected every veterinarian to be reachable by scrolling");
+        assertEquals("Zz120", tester.getCellText(125, LAST_NAME),
+                "Expected the last chunk to be fetched and appended");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVeterinariansRendersAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected the veterinarians grid to be rendered even when empty");
+        assertEquals(0, vetsGrid().size(), "Expected no rows");
+    }
+
+    @SuppressWarnings("unchecked")
+    private GridTester<Grid<Object>, Object> vetsGrid() {
+        return test(find(Grid.class).single());
+    }
+}
